window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[158]={"id":"158","numero":158,"titre":"Sepsis & Choc septique de l'enfant et de l'adulte","objectifs":[{"id":"158-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du sepsis et du choc septique chez l’enfant et l’adulte","contenu":"<p>Le <span class=\"kw-def\">sepsis</span> est un <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> grave traduisant une <strong>réponse inappropriée de l'hôte face à une infection</strong> (<span class=\"kw-etio\">bactérienne</span> dans l'immense majorité des cas), à l'origine d'une <span class=\"kw-clinique\">dysfonction d'organe</span> qui <span class=\"kw-alerte\">menace</span> le <span class=\"kw-alerte\">pronostic vital</span> — à la différence d'une simple infection. Sa survenue dépend de la <span class=\"kw-etio\">virulence du ou des pathogènes</span>, du <span class=\"kw-etio\">site infectieux</span> et des <span class=\"kw-etio\">facteurs de susceptibilité de l'hôte</span>. La <span class=\"kw-clinique\">dysfonction d'organe</span> est le <span class=\"kw-def\">stade</span> qui précède la <span class=\"kw-alerte\">défaillance d'organe</span> (laquelle impose une suppléance artificielle).</p>\n      <p>Le diagnostic de <span class=\"kw-def\">sepsis</span> repose sur une infection associée à une dysfonction d'organe, <strong>même en l'absence de <span class=\"kw-alerte\">choc</span></strong> : il est retenu si le <span class=\"kw-def\">score</span> <span class=\"kw-def\">qSOFA</span> atteint <span class=\"kw-chiffre\">2</span> (ou augmente de 2).</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Sepsis</span></th><th><span class=\"kw-def\">Choc septique</span></th></tr></thead>\n        <tbody>\n          <tr><td>Définition</td><td>Infection + dysfonction d'organe menaçant le <span class=\"kw-alerte\">pronostic vital</span></td><td><span class=\"kw-def\">Sepsis</span> avec anomalies circulatoires, cellulaires et métaboliques profondes</td></tr>\n          <tr><td>Critère opérationnel</td><td><span class=\"kw-def\">qSOFA ≥ 2</span></td><td><span class=\"kw-def\">Sepsis</span> réfractaire à la PEC initiale + <span class=\"kw-bio\">lactates</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> + besoin de <span class=\"kw-ttt\">vasopresseurs</span> pour <span class=\"kw-chiffre\">PAM ≥ 65 mmHg</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span></td><td><span class=\"kw-chiffre\">&gt; 10 %</span></td><td><span class=\"kw-chiffre\">&gt; 40 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Score</span> <span class=\"kw-chiffre\">qSOFA</span></strong> (<em>quick <span class=\"kw-chiffre\">SOFA</span></em>, <span class=\"kw-def\">dépistage</span> rapide au lit) — 3 items, 1 point chacun :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fréquence respiratoire</span> <span class=\"kw-chiffre\">≥ 22/min</span></li>\n        <li><span class=\"kw-clinique\">PAS</span> <span class=\"kw-chiffre\">≤ 100 mmHg</span></li>\n        <li><span class=\"kw-clinique\">Troubles des fonctions supérieures</span> (<span class=\"kw-chiffre\">Glasgow &lt; 15</span>)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège diagnostique.</strong> Le diagnostic de <span class=\"kw-def\">choc septique</span> ne peut se poser qu'<strong>après la prise en charge initiale</strong> fondée sur l'expansion volémique : c'est l'<span class=\"kw-clinique\">hypotension</span> <span class=\"kw-alerte\">réfractaire au remplissage</span> et nécessitant des amines qui le définit.</div>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> — cascade en 4 temps :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Réponse immune excessive</td><td><span class=\"kw-def\">Orage cytokinique</span> ; activation du <span class=\"kw-bio\">complément</span> et de la coagulation (<span class=\"kw-alerte\">hypercoagulabilité</span>) ; réponse anti-<span class=\"kw-etio\">inflammatoire</span> excessive (<span class=\"kw-alerte\">immunodépression du sepsis</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Défaillance</span> macrocirculatoire</td><td><span class=\"kw-def\">Vasoplégie</span> ; <span class=\"kw-def\">hyperperméabilité capillaire</span> → <span class=\"kw-alerte\">hypovolémie efficace</span> ; phase chaude (<span class=\"kw-clinique\">tachycardie</span> compensatrice) puis phase froide (<span class=\"kw-alerte\">défaillance</span> cardiaque)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Défaillance</span> microcirculatoire</td><td><span class=\"kw-clinique\">Œdème</span> interstitiel ; microthrombi obstruant <span class=\"kw-clinique\">les</span> capillaires → <span class=\"kw-alerte\">altération de l'extraction d'O₂</span></td></tr>\n          <tr><td>Dysoxie tissulaire</td><td>Métabolisme <span class=\"kw-etio\">anaérobie</span> → <span class=\"kw-bio\">acidose métabolique</span> + <span class=\"kw-bio\">hyperlactatémie</span> → défaillances d'organes, pouvant évoluer vers le <span class=\"kw-alerte\">syndrome de défaillance multiviscérale</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":2},{"id":"158-2","rang":"A","rubrique":"Identifier une urgence","titre":"Reconnaître un patient à risque","contenu":"<p>Reconnaître précocement un <span class=\"kw-alerte\">patient à risque</span> de <span class=\"kw-def\">sepsis</span> ou de gravité est un objectif Rang A majeur : tout <span class=\"kw-def\">terrain</span> favorisant doit être recherché systématiquement à l'anamnèse devant un <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>.</p>\n      <p><strong>Terrains favorisants à rechercher :</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Contact récent avec le milieu de soins</span> (<span class=\"kw-alerte\">hospitalisation</span>, EHPAD)</li>\n        <li><span class=\"kw-etio\">Gestes invasifs récents</span> et/ou présence de <span class=\"kw-etio\">matériel étranger</span> (cathéter, prothèse, sonde)</li>\n        <li><span class=\"kw-etio\">Pathologies ou facteurs de risque d'infection</span>, <span class=\"kw-alerte\">immunodépression</span> (cancer, <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">corticothérapie</span>, asplénie, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">diabète</span>)</li>\n        <li><span class=\"kw-etio\">Prise récente de traitements anti-infectieux</span> (sélection de résistances)</li>\n        <li><span class=\"kw-etio\">Éthylisme</span></li>\n        <li><span class=\"kw-etio\">Brèche ostéo-méningée</span></li>\n        <li><span class=\"kw-etio\">Retour de pays tropical</span> ou de <span class=\"kw-etio\">zone d'endémie palustre</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Pourquoi c'est clé.</strong> Le <span class=\"kw-def\">terrain</span> oriente à la fois le <span class=\"kw-etio\">germe probable</span> et le <span class=\"kw-ttt\">choix de l'antibiothérapie probabiliste</span> : un patient en <span class=\"kw-def\">contact</span> avec <span class=\"kw-clinique\">les</span> soins relève d'une couverture large des <span class=\"kw-etio\">bactéries multirésistantes</span>, un retour de zone d'endémie impose d'éliminer un <span class=\"kw-alerte\">paludisme grave</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":4},{"id":"158-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer un état de choc septique chez l’enfant et l’adulte","contenu":"<p>La <strong>suspicion clinique d'infection suffit</strong> à débuter la démarche. Devant tout <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, on recherche activement un <span class=\"kw-alerte\">état de choc</span> en s'appuyant sur trois ensembles de signes.</p>\n      <p><strong>1. <span class=\"kw-clinique\">Hypotension</span> artérielle</strong> (non <span class=\"kw-etio\">iatrogène</span> — hors sédation, anesthésie) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">PAS</span> <span class=\"kw-chiffre\">&lt; 90 mmHg</span>, ou chute <span class=\"kw-chiffre\">&gt; 40 mmHg</span> <span class=\"kw-bio\">vs</span> valeur initiale, ou chute <span class=\"kw-chiffre\">&gt; 30 %</span> chez l'hypertendu</li>\n        <li><span class=\"kw-clinique\">PAM</span> <span class=\"kw-chiffre\">&lt; 60-65 mmHg</span></li>\n        <li><span class=\"kw-clinique\">PAD</span> <span class=\"kw-chiffre\">&lt; 40 mmHg</span></li>\n      </ul>\n      <p><strong>2. Au moins une <span class=\"kw-alerte\">défaillance</span> d'organe / signe d'hypoperfusion</strong> (mécanismes de compensation visant à maintenir le débit cardiaque) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Tachycardie réflexe</span> <span class=\"kw-chiffre\">&gt; 120 bpm</span> — prudence sous <span class=\"kw-ttt\">β-bloquants</span> (<span class=\"kw-clinique\">tachycardie</span> masquée)</li>\n        <li><span class=\"kw-clinique\">Polypnée</span> <span class=\"kw-chiffre\">&gt; 22/min</span></li>\n        <li><span class=\"kw-clinique\">Marbrures</span> — débutent aux genoux ; leur extension est corrélée à la gravité, leur régression est un signe d'amélioration</li>\n        <li><span class=\"kw-clinique\">Extrémités froides et cyanosées</span></li>\n        <li><span class=\"kw-clinique\">Temps de recoloration cutanée</span> allongé (<span class=\"kw-chiffre\">&gt; 3-5 s</span>, au genou ou à l'index)</li>\n        <li><span class=\"kw-clinique\">Confusion, agitation</span></li>\n        <li><span class=\"kw-clinique\">Oligurie</span> (<span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span> ou <span class=\"kw-chiffre\">&lt; 500 mL/j</span>)</li>\n      </ul>\n      <p><strong>3. Dosages indispensables</strong> : <span class=\"kw-bio\">lactatémie</span> + <span class=\"kw-bio\">gaz du sang</span> → une <span class=\"kw-bio\">hyperlactatémie</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> et une <span class=\"kw-bio\">acidose métabolique</span> sont des arguments forts, corrélés à la gravité.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une <span class=\"kw-alerte\">PA normale n'élimine pas</span> un <span class=\"kw-def\">choc septique</span> débutant : la phase chaude maintient la pression par <span class=\"kw-clinique\">tachycardie</span> et vasoconstriction. Un <span class=\"kw-alerte\">coma</span>, en revanche, doit faire suspecter un autre mécanisme (<span class=\"kw-etio\">méningo-encéphalite</span>, hématome).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":2},{"id":"158-4","rang":"A","rubrique":"Diagnostic positif","titre":"Reconnaitre un purpura fulminans","contenu":"<p>Le <span class=\"kw-alerte\">purpura fulminans</span> est une <span class=\"kw-alerte\">urgence</span> vitale absolue : c'est un <span class=\"kw-def\">sepsis</span> avec <span class=\"kw-clinique\">purpura</span> nécrotique extensif, le plus souvent d'origine méningococcique. Sa reconnaissance repose sur <strong>trois critères simultanés</strong>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Purpura</span> nécrotique extensif</td><td>Lésions <span class=\"kw-chiffre\">≥ 3 mm</span>, <span class=\"kw-clinique\">ne s'effaçant pas à la vitropression</span>, à <span class=\"kw-alerte\">extension rapide</span> (en quelques heures)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span></td><td><span class=\"kw-clinique\">Fièvre élevée</span> (souvent <span class=\"kw-chiffre\">&gt; 39 °C</span>) ; parfois <span class=\"kw-alerte\">hypothermie</span> chez le nourrisson</td></tr>\n          <tr><td>Signes de <span class=\"kw-alerte\">choc</span> / <span class=\"kw-def\">sepsis</span></td><td><span class=\"kw-clinique\">Marbrures</span> ; <span class=\"kw-clinique\">TRC allongé</span> ; <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-clinique\">troubles de conscience</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> absolue.</strong> Le diagnostic est <strong>clinique, au lit du patient, en moins de 30 secondes</strong>. Il n'attend aucun examen complémentaire : l'<span class=\"kw-ttt\">antibiothérapie par C3G</span> doit être injectée immédiatement, avant même le transport.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":0},{"id":"158-5","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir rechercher sur les éléments de l’anamnèse et l’examen clinique les éléments d’orientation pour déterminer le site infectieux","contenu":"<p>L'anamnèse et l'examen clinique recherchent le <span class=\"kw-etio\">foyer infectieux</span>. Par ordre de fréquence : <span class=\"kw-etio\">pulmonaire</span>, <span class=\"kw-etio\">intra-abdominal</span>, <span class=\"kw-etio\">urinaire</span>.</p>\n      <p><strong>Signes d'orientation par appareil :</strong></p>\n      <ul>\n        <li><strong>Pulmonaire :</strong> <span class=\"kw-clinique\">foyer auscultatoire</span> ; <span class=\"kw-radio\">condensation alvéolaire</span> radiographique</li>\n        <li><strong>Digestif :</strong> <span class=\"kw-clinique\">signes digestifs</span> ; <span class=\"kw-clinique\">défense abdominale</span> localisée ou diffuse</li>\n        <li><strong>Urinaire :</strong> <span class=\"kw-clinique\">signes de cystite</span> ; aspect des urines ; <span class=\"kw-bio\">BU leucocytes + nitrites positifs</span> ; <span class=\"kw-clinique\">douleur du flanc</span></li>\n        <li><strong>Ostéo-articulaire :</strong> <span class=\"kw-clinique\">douleurs articulaires ou rachidiennes</span> ; signes d'<span class=\"kw-clinique\">arthrite</span></li>\n        <li><strong>Sur matériel :</strong> <span class=\"kw-clinique\">cicatrices</span> témoignant d'un matériel étranger</li>\n        <li><strong>Neuro-méningé :</strong> <span class=\"kw-clinique\">signes neurologiques focaux</span> ou <span class=\"kw-clinique\">signes méningés</span></li>\n      </ul>\n      <p><strong>Orientation <span class=\"kw-clinique\">porte d'entrée</span> → germe :</strong></p>\n      <table >\n        <thead><tr><th>Germe</th><th>Porte d'entrée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Streptocoque oral</span></td><td>Cavité buccale</td></tr>\n          <tr><td><span class=\"kw-etio\">Pneumocoque</span></td><td>Poumon ; méninges ; ORL</td></tr>\n          <tr><td><span class=\"kw-etio\">Anaérobies</span></td><td>Cavité buccale ; côlon ; pelvis</td></tr>\n          <tr><td><span class=\"kw-etio\">Streptococcus pyogenes</span></td><td>Peau</td></tr>\n          <tr><td><span class=\"kw-etio\">Staphylocoque</span></td><td>Peau</td></tr>\n          <tr><td><span class=\"kw-etio\">E. coli, entérobactéries, entérocoques</span></td><td>Voies urinaires ; tube digestif ; voies biliaires ; cathéter vasculaire</td></tr>\n          <tr><td><span class=\"kw-etio\">Candida</span></td><td>Tube digestif ; cathéter vasculaire</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":1},{"id":"158-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un état de choc septique (hors microbiologie)","contenu":"<p>Le diagnostic d'<span class=\"kw-def\">état de choc septique</span> associe la reconnaissance clinique de l'hypoperfusion, la confirmation <span class=\"kw-ttt\">biologique</span> et le bilan systématique de gravité — la microbiologie est traitée à part.</p>\n      <p><strong>Recherche des défaillances d'organes</strong> — tableau clinique et paraclinique organe par organe :</p>\n      <table >\n        <thead><tr><th>Organe</th><th>Signes cliniques</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Cerveau</td><td><span class=\"kw-clinique\">Angoisse, agitation, confusion</span> ; <span class=\"kw-alerte\">prostration, obnubilation, coma</span> (<span class=\"kw-chiffre\">Glasgow ≤ 8</span>)</td><td>—</td></tr>\n          <tr><td>Circulation</td><td><span class=\"kw-clinique\">Tachycardie</span> (<span class=\"kw-chiffre\">FC &gt; 120 bpm</span>) ; <span class=\"kw-clinique\">hypotension</span> (<span class=\"kw-chiffre\">PAS &lt; 90</span>, <span class=\"kw-chiffre\">PAD &lt; 40</span>, <span class=\"kw-chiffre\">PAM &lt; 65-70 mmHg</span>)</td><td><span class=\"kw-bio\">Monitorage du débit cardiaque</span> (calcul des RVS)</td></tr>\n          <tr><td>Cœur</td><td><span class=\"kw-alerte\">IDM, sidération myocardique</span> ; <span class=\"kw-alerte\">troubles du rythme, arrêt cardiaque</span></td><td><span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">ETT</span> ; <span class=\"kw-bio\">élévation des CPK et de la troponine Ic</span></td></tr>\n          <tr><td>Peau</td><td><span class=\"kw-clinique\">Marbrures</span> ; <span class=\"kw-clinique\">pâleur</span> ; <span class=\"kw-clinique\">extrémités froides et cyanosées</span> ; <span class=\"kw-clinique\">TRC &gt; 3-5 s</span></td><td>—</td></tr>\n          <tr><td>Poumons</td><td><span class=\"kw-clinique\">Polypnée superficielle</span> <span class=\"kw-chiffre\">&gt; 24/min</span> ; <span class=\"kw-clinique\">tirage</span> ; <span class=\"kw-clinique\">hypoxémie</span> (<span class=\"kw-chiffre\">SpO₂ &lt; 90 %</span>)</td><td><span class=\"kw-bio\">Gaz du sang artériel</span> ; <span class=\"kw-bio\">hypocapnie &lt; 32 mmHg</span> ; <span class=\"kw-chiffre\">PaO₂/FiO₂ &lt; 300</span></td></tr>\n          <tr><td>Métabolisme</td><td><span class=\"kw-bio\">Acidose métabolique</span> ; <span class=\"kw-clinique\">polypnée d'acidose</span> ; <span class=\"kw-clinique\">insulino-résistance</span></td><td><span class=\"kw-bio\">Lactatémie &gt; 2 mmol/L</span> ; <span class=\"kw-bio\">SvcO₂ &lt; 70 %</span> ; <span class=\"kw-bio\">hyperglycémie</span></td></tr>\n          <tr><td>Reins</td><td><span class=\"kw-clinique\">Oligurie</span> (<span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span> ou <span class=\"kw-chiffre\">&lt; 500 mL/j</span>) ; <span class=\"kw-alerte\">anurie</span></td><td><span class=\"kw-bio\">Créatininémie ≥ 26,5 µmol/L</span> ou <span class=\"kw-chiffre\">≥ 1,5 × la valeur de base</span></td></tr>\n          <tr><td>Foie</td><td><span class=\"kw-clinique\">Ictère</span> ; <span class=\"kw-alerte\">encéphalopathie hépatique</span> ; <span class=\"kw-clinique\">saignements, œdème</span></td><td><span class=\"kw-bio\">Bilirubinémie ≥ 35 µmol/L</span> ; <span class=\"kw-bio\">ASAT/ALAT ≥ 1,5 × N</span> ; <span class=\"kw-bio\">baisse &gt; 30 % des facteurs de coagulation</span></td></tr>\n          <tr><td>Tube digestif</td><td><span class=\"kw-clinique\">Iléus</span> voire <span class=\"kw-alerte\">abdomen aigu</span> ; <span class=\"kw-alerte\">ischémie mésentérique</span></td><td><span class=\"kw-imagerie\">Scanner abdomino-pelvien injecté</span></td></tr>\n          <tr><td>Endothélium</td><td><span class=\"kw-alerte\">Saignement diffus en nappe</span> ; <span class=\"kw-clinique\">purpura</span> ; <span class=\"kw-alerte\">ischémie des extrémités</span></td><td><span class=\"kw-bio\">Plaquettes &lt; 100 000/mm³</span> ; <span class=\"kw-bio\">INR &gt; 1,5</span> ; <span class=\"kw-bio\">TCA &gt; 60 s</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan d'évaluation de la gravité</strong> (hors microbiologie) — à réaliser sans retarder la prise en charge :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Lactatémie</span> + <span class=\"kw-bio\">gaz du sang</span> — systématiques</li>\n        <li><span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">bilan d'hémostase</span> (recherche de <span class=\"kw-alerte\">CIVD</span>)</li>\n        <li><span class=\"kw-bio\">Bilan hépatique</span> (cytolyse / <span class=\"kw-clinique\">cholestase</span> : « foie de <span class=\"kw-alerte\">choc</span> »)</li>\n        <li><span class=\"kw-bio\">Ionogramme</span> + <span class=\"kw-bio\">créatininémie</span> + <span class=\"kw-bio\">urée</span> (recherche d'<span class=\"kw-etio\">IRA</span>)</li>\n        <li><span class=\"kw-imagerie\">ECG</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"158-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des prélèvements microbiologiques d’urgence avant antibiothérapie","contenu":"<p><span class=\"kw-clinique\">Les</span> prélèvements microbiologiques d'<span class=\"kw-alerte\">urgence</span> sont réalisés <strong>avant l'<span class=\"kw-ttt\">antibiothérapie</span></strong>, mais <strong>sans la retarder</strong>.</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Hémocultures</span></strong> — <span class=\"kw-def\">seul examen microbiologique indispensable avant l'antibiothérapie</span> ; positives dans seulement <span class=\"kw-chiffre\">~30 %</span> des <span class=\"kw-def\">sepsis</span></li>\n        <li><strong><span class=\"kw-bio\">Bandelette urinaire</span></strong> ± <span class=\"kw-bio\">ECBU</span> si la <span class=\"kw-bio\">BU</span> est positive</li>\n        <li><strong><span class=\"kw-bio\">Aspiration endotrachéale</span></strong> si le patient est intubé</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Exception capitale.</strong> En cas de <span class=\"kw-alerte\">purpura fulminans</span>, ce principe est inversé : l'<span class=\"kw-ttt\">antibiothérapie IV/IM</span> est injectée <strong>immédiatement</strong>, avant <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> et avant le transport.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":1},{"id":"158-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des prélèvements microbiologiques adaptés à la suspicion d’infection","contenu":"<p>Au-delà des <span class=\"kw-bio\">hémocultures</span> systématiques, <span class=\"kw-clinique\">les</span> prélèvements microbiologiques et l'imagerie sont <strong>orientés par la clinique</strong>, à la recherche du foyer.</p>\n      <table >\n        <thead><tr><th>Suspicion de foyer</th><th>Prélèvement / imagerie ciblés</th></tr></thead>\n        <tbody>\n          <tr><td>Urinaire</td><td><span class=\"kw-bio\">ECBU</span> ± imagerie des voies urinaires</td></tr>\n          <tr><td>Méningé</td><td><span class=\"kw-bio\">Ponction lombaire</span> ± <span class=\"kw-imagerie\">imagerie cérébrale</span></td></tr>\n          <tr><td>Pulmonaire</td><td><span class=\"kw-bio\">Prélèvement respiratoire</span> / aspiration ; <span class=\"kw-imagerie\">radiographie thoracique</span></td></tr>\n          <tr><td>Digestif / intra-abdominal</td><td><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span> ; <span class=\"kw-ttt\">ponction</span> de collection</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Imagerie :</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Radiographie thoracique</span> — au minimum, dans tous <span class=\"kw-clinique\">les</span> cas</li>\n        <li><span class=\"kw-imagerie\">TDM</span> orientée par la clinique ; ou <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> en l'absence de point d'appel, pour rechercher un foyer profond</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":3},{"id":"158-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser pour diagnostiquer les complications du choc","contenu":"<p>Une fois le <span class=\"kw-alerte\">choc</span> reconnu, des examens ciblés explorent et surveillent <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">complications</span> de chaque <span class=\"kw-alerte\">défaillance</span> d'organe.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Dysoxie tissulaire</td><td><span class=\"kw-bio\">Gaz du sang</span> ; <span class=\"kw-bio\">lactatémie</span> (cinétique répétée)</td></tr>\n          <tr><td><span class=\"kw-alerte\">CIVD</span></td><td><span class=\"kw-bio\">NFS-plaquettes</span> ; <span class=\"kw-bio\">TP/TCA</span> ; <span class=\"kw-bio\">fibrinogène</span> ; <span class=\"kw-bio\">D-dimères</span></td></tr>\n          <tr><td>Foie de <span class=\"kw-alerte\">choc</span></td><td><span class=\"kw-bio\">Bilirubine</span> ; <span class=\"kw-bio\">ASAT/ALAT</span> ; <span class=\"kw-bio\">TP / facteurs de coagulation</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Insuffisance rénale aiguë</span></td><td><span class=\"kw-bio\">Créatininémie</span> ; <span class=\"kw-bio\">urée</span> ; <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-clinique\">diurèse</span></td></tr>\n          <tr><td>Atteinte myocardique</td><td><span class=\"kw-imagerie\">ECG</span> ; <span class=\"kw-bio\">CPK</span> ; <span class=\"kw-bio\">troponine</span> ; <span class=\"kw-imagerie\">ETT</span></td></tr>\n          <tr><td>Ischémie mésentérique</td><td><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1},{"id":"158-10","rang":"A","rubrique":"Examens complémentaires","titre":"Comprendre l’intérêt (ou pas) d’un dosage de la CRP et de la PCT dans le contexte de sepsis et de choc septique","contenu":"<p>La <span class=\"kw-bio\">CRP</span> et la <span class=\"kw-bio\">procalcitonine (PCT)</span> sont des biomarqueurs de l'inflammation. Ils ont une <strong>bonne valeur prédictive négative</strong> mais sont <span class=\"kw-alerte\">peu spécifiques</span>.</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">CRP</span> :</strong> élévation non spécifique, sans seuil décisionnel utile dans le contexte de <span class=\"kw-def\">sepsis</span>.</li>\n        <li><strong><span class=\"kw-bio\">PCT</span> :</strong> un peu plus spécifique d'une infection <span class=\"kw-etio\">bactérienne</span> ; une valeur <span class=\"kw-chiffre\">&lt; 0,25 ng/mL</span> rend une <span class=\"kw-clinique\">bactériémie</span> ou une fongémie peu probable. <strong>Dosage non systématique</strong>, d'intérêt limité à de rares situations.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Message clé.</strong> En présence de signes <span class=\"kw-etio\">infectieux</span> <strong>et</strong> d'une dysfonction d'organe, l'<span class=\"kw-ttt\">antibiothérapie est prescrite systématiquement</span>, <span class=\"kw-alerte\">quelle que soit la valeur de la CRP ou de la PCT</span>. Ces biomarqueurs ne modifient pas la décision de traiter un <span class=\"kw-def\">sepsis</span> ou un <span class=\"kw-def\">choc septique</span>.</div>","frequence":0},{"id":"158-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales infections responsables de sepsis et de choc septique chez l’adulte et l’enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> infections responsables de <span class=\"kw-def\">sepsis</span> et de <span class=\"kw-def\">choc septique</span> sont dominées, par ordre de fréquence, par trois grands foyers — communs à l'adulte et à l'enfant.</p>\n      <table >\n        <thead><tr><th>Foyer</th><th>Germes / particularités</th></tr></thead>\n        <tbody>\n          <tr><td>Pulmonaire (le plus fréquent)</td><td><span class=\"kw-etio\">Pneumocoque</span> ; <span class=\"kw-etio\">entérobactéries</span> ; germes intracellulaires</td></tr>\n          <tr><td>Intra-abdominal</td><td><span class=\"kw-etio\">Entérobactéries</span> ; <span class=\"kw-etio\">anaérobies</span> ; <span class=\"kw-etio\">entérocoques</span></td></tr>\n          <tr><td>Urinaire</td><td><span class=\"kw-etio\">E. coli</span> et autres <span class=\"kw-etio\">entérobactéries</span></td></tr>\n          <tr><td>Cutané / parties molles</td><td><span class=\"kw-etio\">Streptococcus pyogenes</span> ; <span class=\"kw-etio\">Staphylocoque doré</span></td></tr>\n          <tr><td>Sur cathéter / matériel</td><td><span class=\"kw-etio\">Staphylocoques</span> ; <span class=\"kw-etio\">Candida</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Particularités pédiatriques :</strong> chez l'enfant, le <span class=\"kw-etio\">méningocoque</span> et le <span class=\"kw-etio\">pneumocoque</span> tiennent une place majeure parmi <span class=\"kw-clinique\">les</span> causes de <span class=\"kw-def\">sepsis</span> grave et de <span class=\"kw-clinique\">purpura</span> fulminans.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":2},{"id":"158-12","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes du purpura fulminans","contenu":"<p>Le <span class=\"kw-alerte\">purpura fulminans</span> est d'origine <span class=\"kw-etio\">bactérienne</span> ; deux germes dominent largement.</p>\n      <table >\n        <thead><tr><th>Germe</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Méningocoque</span> (<em>Neisseria meningitidis</em>)</td><td><strong>Cause la plus fréquente.</strong> Sérogroupes B et C surtout. Pics d'<span class=\"kw-def\">incidence</span> : <span class=\"kw-chiffre\">3 mois - 2 ans</span> et <span class=\"kw-chiffre\">14-19 ans</span>. <span class=\"kw-alerte\">Déclaration obligatoire.</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Pneumocoque</span> (<em>Streptococcus pneumoniae</em>)</td><td>Cause classique chez l'<span class=\"kw-alerte\">asplénique</span> — splénectomie anatomique ou asplénie fonctionnelle (<span class=\"kw-etio\">drépanocytose</span>). Cadre de l'<span class=\"kw-etio\">OPSI</span> (<em>overwhelming post-splenectomy infection</em>).</td></tr>\n          <tr><td>Plus rares</td><td><span class=\"kw-etio\">Staphylococcus aureus</span> ; <span class=\"kw-etio\">streptocoques</span> ; <span class=\"kw-etio\">Haemophilus influenzae</span> (devenu rare depuis la <span class=\"kw-ttt\">vaccination</span> Hib).</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span></em></p>","frequence":0},{"id":"158-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’initiation de la prise en charge immédiate d’un purpura fulminans avec posologie des C3G par voie intraveineuse","contenu":"<p>Le <span class=\"kw-alerte\">purpura fulminans</span> impose une <strong><span class=\"kw-ttt\">antibiothérapie</span> injectée sur place, sans délai</strong> : chaque minute compte. La prise en charge suit une chronologie stricte.</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td>T0</td><td><strong>Diagnostic clinique au lit</strong> (&lt; 30 s) — sans attendre d'examen ni le transport</td></tr>\n          <tr><td>T0 +<span class=\"kw-chiffre\"> 1 min</span></td><td><strong>Injection immédiate de <span class=\"kw-ttt\">C3G</span></strong> par voie IV ou IM</td></tr>\n          <tr><td>T0 +<span class=\"kw-chiffre\"> 2 min</span></td><td><strong>Appel <span class=\"kw-alerte\">SAMU</span> (15)</strong> — transport médicalisé vers la <span class=\"kw-alerte\">réanimation</span></td></tr>\n          <tr><td>T0 +<span class=\"kw-chiffre\"> 5-15 min</span></td><td>Mesures associées : décubitus ± Trendelenburg (si pas de <span class=\"kw-alerte\">détresse</span> respiratoire) ; <span class=\"kw-ttt\">O₂</span> fort débit ; pose d'une VVP ; <span class=\"kw-ttt\">remplissage par cristalloïdes</span> si <span class=\"kw-alerte\">choc</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Posologie des C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> par voie intraveineuse</strong> — à connaître précisément :</p>\n      <table >\n        <thead><tr><th></th><th>Adulte</th><th>Enfant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Céfotaxime</span></td><td><span class=\"kw-chiffre\">1-2 g</span> IV (ou <span class=\"kw-chiffre\">50 mg/kg</span>)</td><td><span class=\"kw-chiffre\">50 mg/kg</span> IV</td></tr>\n          <tr><td><span class=\"kw-ttt\">Ceftriaxone</span></td><td><span class=\"kw-chiffre\">1-2 g</span> IV ou IM</td><td><span class=\"kw-chiffre\">50-100 mg/kg</span> IV ou IM (max <span class=\"kw-chiffre\">2 g</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Voie d'abord.</strong> En l'absence de voie veineuse, ne pas perdre de temps : injection <span class=\"kw-ttt\">IM</span> (face antéro-latérale de la cuisse) ou par <span class=\"kw-ttt\">voie intra-osseuse</span> (tibia proximal / fémur distal chez l'enfant).</div>\n      <div class=\"callout callout-warn\"><strong>Après le geste.</strong> Le <span class=\"kw-clinique\">purpura</span> fulminans relève d'une <span class=\"kw-alerte\">déclaration obligatoire</span> ; l'identification des sujets-contacts en vue d'une <span class=\"kw-ttt\">antibioprophylaxie</span> est organisée secondairement (modalités détaillées dans l'item 151).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-def\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span></em></p>","frequence":4},{"id":"158-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les bases de la prise en charge d’un choc septique chez l’adulte et l’enfant (voir item 332)","contenu":"<p>La prise en charge d'un <span class=\"kw-def\">choc septique</span> est une <strong><span class=\"kw-alerte\">urgence</span> thérapeutique</strong> structurée autour du <span class=\"kw-def\">bundle de la 1ʳᵉ heure</span>, des objectifs de remplissage et de l'orientation du patient. Le détail hémodynamique (catécholamines) relève de l'item 332.</p>\n      <p><strong>Orientation :</strong> milieu permettant une <span class=\"kw-def\">surveillance</span> rapprochée (déchocage des urgences, SSPI, <span class=\"kw-alerte\">réanimation</span>). <span class=\"kw-alerte\">En l'absence d'amélioration à 1 heure → transfert et prise en charge en réanimation obligatoires.</span></p>\n      <p><strong>Bundle de la 1ʳᵉ heure</strong> — non négociable :</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Prélèvements</td><td><span class=\"kw-bio\">Lactatémie</span> + <span class=\"kw-bio\">hémocultures</span> — avant l'<span class=\"kw-ttt\">antibiothérapie</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibiothérapie</span></td><td><span class=\"kw-ttt\">Antibiothérapie large spectre IV</span>, probabiliste, orientée selon la <span class=\"kw-clinique\">porte d'entrée</span></td></tr>\n          <tr><td>Remplissage</td><td><span class=\"kw-ttt\">Cristalloïdes 30 mL/kg</span> (<span class=\"kw-ttt\">Ringer lactate</span> de préférence ; <span class=\"kw-ttt\">NaCl 0,9 %</span> possible)</td></tr>\n          <tr><td>Vasopresseurs</td><td><span class=\"kw-ttt\">Noradrénaline</span> en 1ʳᵉ intention si <span class=\"kw-chiffre\">PAD &lt; 40</span> ou <span class=\"kw-chiffre\">PAM &lt; 65 mmHg</span> pendant ou après le remplissage</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Objectifs du remplissage :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">PAM</span> <span class=\"kw-chiffre\">≥ 65 mmHg</span></li>\n        <li><span class=\"kw-clinique\">Diurèse</span> <span class=\"kw-chiffre\">≥ 0,5 mL/kg/h</span></li>\n        <li><span class=\"kw-clinique\">Régression des marbrures</span></li>\n        <li><span class=\"kw-bio\">Correction progressive de la lactatémie</span></li>\n      </ul>\n      <p><strong>Mesures associées :</strong> <span class=\"kw-ttt\">monitorage</span> (scope, PA, SpO₂, <span class=\"kw-def\">surveillance</span> horaire de la diurèse — cathéter artériel et VVC dans l'idéal) ; <span class=\"kw-ttt\">oxygénothérapie</span> non systématique, cible <span class=\"kw-chiffre\">SpO₂ 96 %</span> si défaut d'apport associé ; sédation et assistance respiratoire au cas par cas ; éradication du foyer <span class=\"kw-etio\">infectieux</span>.</p>\n      <div class=\"callout callout-info\"><strong>Spécificité pédiatrique.</strong> Chez l'enfant, le remplissage initial est de <span class=\"kw-chiffre\">20 mL/kg</span> de cristalloïdes (et non <span class=\"kw-chiffre\">30 mL</span>/kg comme chez l'adulte), avec <span class=\"kw-alerte\">réévaluation après chaque bolus</span> — risque de surcharge volémique chez le nourrisson.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1},{"id":"158-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription précoce des antibiotiques adaptés","contenu":"<p>L'<span class=\"kw-ttt\">antibiothérapie probabiliste</span> est un pilier du bundle : elle est débutée <strong>dans la première heure</strong> suivant la reconnaissance du <span class=\"kw-def\">sepsis</span> grave ou du <span class=\"kw-def\">choc septique</span>.</p>\n      <ul>\n        <li><strong>Spectre :</strong> <span class=\"kw-ttt\">large spectre</span>, le plus souvent par voie <span class=\"kw-ttt\">IV</span>, parfois en <span class=\"kw-ttt\">bi-antibiothérapie</span></li>\n        <li><strong>Choix :</strong> orienté selon la <span class=\"kw-etio\">porte d'entrée présumée</span> et le <span class=\"kw-def\">terrain</span></li>\n        <li><strong>Délai :</strong> chaque heure de retard aggrave le <span class=\"kw-def\">pronostic</span> — l'<span class=\"kw-ttt\">antibiothérapie</span> ne doit pas attendre l'imagerie</li>\n        <li><strong>Suite :</strong> <span class=\"kw-def\">réévaluation</span>, <span class=\"kw-ttt\">désescalade</span> vers un spectre étroit dès l'identification du germe, durée adaptée au foyer</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À savoir.</strong> Le détail de l'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste par foyer (<span class=\"kw-etio\">pneumonie</span>, <span class=\"kw-etio\">infection urinaire</span>, infection intra-abdominale, etc.) et la désescalade par germe relèvent de l'item 157.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":0},{"id":"158-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de contrôle de la source infectieuse","contenu":"<p>Le <span class=\"kw-def\">contrôle de la source</span> est un geste essentiel, complémentaire de l'<span class=\"kw-ttt\">antibiothérapie</span> : il vise à éradiquer un foyer <span class=\"kw-etio\">infectieux</span> non contrôlable par <span class=\"kw-clinique\">les</span> seuls antibiotiques. Il ne doit pas retarder la <span class=\"kw-alerte\">réanimation</span> initiale.</p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Drainage</span></strong> d'un foyer collecté : <span class=\"kw-clinique\">abcès</span> intra-abdominal, <span class=\"kw-imagerie\">épanchement pleural</span> purulent, <span class=\"kw-clinique\">angiocholite</span>, urines infectées en amont d'un obstacle</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span></strong> en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-clinique\">péritonite</span> ; excision des tissus nécrotiques d'une <span class=\"kw-alerte\">dermohypodermite nécrosante</span></li>\n        <li><strong><span class=\"kw-ttt\">Ablation</span></strong> d'un dispositif d'abord vasculaire infecté (cathéter, chambre implantable)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Principe.</strong> Tant que la source n'est pas contrôlée, le <span class=\"kw-def\">sepsis</span> reste entretenu malgré une <span class=\"kw-ttt\">antibiothérapie</span> adaptée — le geste est souvent <span class=\"kw-alerte\">décisif sur le pronostic</span>.</div>","frequence":0},{"id":"158-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription d’antibiotique spécifique chez les patients atteints d’infections non communautaires","contenu":"<p>Une <span class=\"kw-def\">infection non communautaire</span> (liée aux soins, nosocomiale) survient sur un <span class=\"kw-def\">terrain</span> exposé aux <span class=\"kw-alerte\">bactéries multirésistantes</span> : l'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste doit y être <strong>élargie</strong> par rapport à une infection communautaire.</p>\n      <table >\n        <thead><tr><th>Contexte</th><th><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</th></tr></thead>\n        <tbody>\n          <tr><td>Communautaire, <span class=\"kw-clinique\">porte d'entrée</span> non identifiée</td><td><span class=\"kw-ttt\">C3G</span> parentérale (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) ± <span class=\"kw-ttt\">aminoside</span></td></tr>\n          <tr><td>Lié aux soins / non communautaire</td><td><span class=\"kw-ttt\">β-lactamine à très large spectre</span> couvrant <em><span class=\"kw-etio\">Pseudomonas</span></em> et entérobactéries <span class=\"kw-bio\">BLSE</span> (<span class=\"kw-ttt\">pipéracilline-tazobactam</span>, céfépime ou carbapénème selon le risque) + <span class=\"kw-ttt\">amikacine</span></td></tr>\n          <tr><td>Dispositif intravasculaire / risque de <span class=\"kw-bio\">SARM</span></td><td>Ajout d'un <span class=\"kw-ttt\">glycopeptide</span> (<span class=\"kw-ttt\">vancomycine</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Cette <span class=\"kw-ttt\">antibiothérapie</span> reste <strong>probabiliste</strong> : elle est réévaluée et <span class=\"kw-ttt\">désescaladée</span> dès l'<span class=\"kw-bio\">antibiogramme</span>. L'élargissement du spectre est guidé par le <span class=\"kw-def\">terrain</span> (<span class=\"kw-def\">contact</span> avec <span class=\"kw-clinique\">les</span> soins, <span class=\"kw-ttt\">antibiothérapie</span> récente, portage connu de <span class=\"kw-etio\">BMR</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":2},{"id":"158-18","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic d’un état de choc septique","contenu":"<p>Le <span class=\"kw-def\">choc septique</span> est une pathologie de <span class=\"kw-alerte\">pronostic sévère</span>. Sa <span class=\"kw-def\">mortalité</span> est étroitement liée au nombre de défaillances d'organes et à la précocité de la prise en charge.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Mortalité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Sepsis</span></td><td><span class=\"kw-chiffre\">&gt; 10 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Choc septique</span></td><td><span class=\"kw-chiffre\">~40 %</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Défaillance</span> multiviscérale (<span class=\"kw-chiffre\">≥ 3 défaillances</span>)</td><td><span class=\"kw-chiffre\">~60-80 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs de mauvais <span class=\"kw-def\">pronostic</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Nombre de défaillances d'organes</span></li>\n        <li><span class=\"kw-bio\">Hyperlactatémie</span> initiale élevée et lentement corrigée</li>\n        <li><span class=\"kw-alerte\">Retard</span> à l'<span class=\"kw-ttt\">antibiothérapie</span> et au remplissage (bundle de la 1ʳᵉ heure)</li>\n        <li><span class=\"kw-def\">Terrain</span> : âge, comorbidités, <span class=\"kw-alerte\">immunodépression</span> ; qualité du contrôle de la source infectieuse</li>\n      </ul>\n      <p>Chez <span class=\"kw-clinique\">les</span> survivants, des <span class=\"kw-alerte\">séquelles post-réanimation</span> sont fréquentes (faiblesse musculaire, troubles neurocognitifs attentionnels et exécutifs, retentissement psychologique) et justifient une réhabilitation et un <span class=\"kw-def\">suivi</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Purpura</span> fulminans :</strong> diagnostic <span class=\"kw-clinique\">clinique</span> au lit en <span class=\"kw-chiffre\">&lt; 30 s</span>, injection de <span class=\"kw-ttt\">C3G</span> IV ou IM <span class=\"kw-alerte\">immédiate</span>, avant tout examen et avant le transport.<br><strong>Bundle de la 1ʳᵉ heure :</strong> <span class=\"kw-bio\">lactatémie</span> + <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-ttt\">antibiothérapie large spectre IV</span> et <span class=\"kw-ttt\">remplissage</span> à débuter dans l’<span class=\"kw-chiffre\">heure</span>.<br><strong><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">H1</span> :</strong> en l’absence d’amélioration → <span class=\"kw-alerte\">transfert en réanimation obligatoire</span>.</p>","hospit":"<p><strong>Orientation :</strong> milieu permettant une <span class=\"kw-def\">surveillance</span> rapprochée — déchocage des urgences, salle de surveillance post-interventionnelle (SSPI) ou <span class=\"kw-alerte\">réanimation</span>.<br><strong>Délai clé :</strong> absence d’amélioration à <span class=\"kw-chiffre\">1 h</span> → <span class=\"kw-alerte\">transfert et prise en charge en réanimation obligatoires</span>.<br><strong><span class=\"kw-clinique\">Purpura</span> fulminans :</strong> appel du <span class=\"kw-alerte\">SAMU</span> (15), transport médicalisé vers la réanimation après l’injection de <span class=\"kw-ttt\">C3G</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Purpura nécrotique extensif</span> (<span class=\"kw-alerte\">purpura fulminans</span>) — lésions <span class=\"kw-chiffre\">≥ 3 mm</span> ne s’effaçant pas à la vitropression, à extension rapide</li><li><span class=\"kw-alerte\">Hypotension réfractaire au remplissage</span> : <span class=\"kw-chiffre\">PAM &lt; 65 mmHg</span> ou <span class=\"kw-chiffre\">PAD &lt; 40 mmHg</span></li><li><span class=\"kw-alerte\">Hyperlactatémie</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> et <span class=\"kw-bio\">acidose métabolique</span></li><li><span class=\"kw-alerte\">Marbrures</span> extensives, <span class=\"kw-clinique\">temps de recoloration cutanée</span> <span class=\"kw-chiffre\">&gt; 3-5 s</span>, extrémités froides et cyanosées</li><li><span class=\"kw-alerte\">Oligurie</span> <span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span> (ou <span class=\"kw-chiffre\">&lt; 500 mL/j</span>), voire anurie</li><li><span class=\"kw-alerte\">Troubles de conscience</span> : confusion, agitation, <span class=\"kw-alerte\">coma</span> (<span class=\"kw-chiffre\">Glasgow &lt; 15</span>)</li><li><span class=\"kw-alerte\">Polypnée</span> <span class=\"kw-chiffre\">&gt; 22/min</span> et <span class=\"kw-alerte\">tachycardie réflexe</span> <span class=\"kw-chiffre\">&gt; 120 bpm</span></li><li><span class=\"kw-alerte\">CIVD</span> et <span class=\"kw-alerte\">syndrome de défaillance multiviscérale</span></li></ul>","principes":"<p><strong>Bundle de la 1ʳᵉ heure</strong></p><ul><li><strong>Prélèvements :</strong> <span class=\"kw-bio\">lactatémie</span> + <span class=\"kw-bio\">hémocultures</span> avant l’<span class=\"kw-ttt\">antibiothérapie</span></li><li><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">large spectre IV</span> probabiliste, orientée selon la porte d’entrée (souvent <span class=\"kw-ttt\">bi-antibiothérapie</span>)</li><li><strong>Remplissage :</strong> <span class=\"kw-ttt\">cristalloïdes</span> <span class=\"kw-chiffre\">30 mL/kg</span> (<span class=\"kw-ttt\">Ringer lactate</span> de préférence, <span class=\"kw-ttt\">NaCl 0,9 %</span> possible) ; <span class=\"kw-chiffre\">20 mL/kg</span> chez l’enfant avec <span class=\"kw-def\">réévaluation</span> après chaque bolus</li><li><strong>Vasopresseurs :</strong> <span class=\"kw-ttt\">noradrénaline</span> en 1ʳᵉ intention si <span class=\"kw-chiffre\">PAD &lt; 40</span> ou <span class=\"kw-chiffre\">PAM &lt; 65 mmHg</span> pendant ou après le remplissage</li></ul><p><strong>Objectifs du remplissage</strong></p><ul><li><span class=\"kw-clinique\">PAM</span> <span class=\"kw-chiffre\">≥ 65 mmHg</span></li><li><span class=\"kw-clinique\">Diurèse</span> <span class=\"kw-chiffre\">≥ 0,5 mL/kg/h</span></li><li><span class=\"kw-clinique\">Régression des marbrures</span></li><li><span class=\"kw-bio\">Correction progressive de la lactatémie</span></li></ul><p><strong><span class=\"kw-clinique\">Purpura</span> fulminans — C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> immédiate</strong></p><ul><li><span class=\"kw-ttt\">Céfotaxime</span> <span class=\"kw-chiffre\">1-2 g</span> IV (<span class=\"kw-chiffre\">50 mg/kg</span> chez l’enfant)</li><li><span class=\"kw-ttt\">Ceftriaxone</span> <span class=\"kw-chiffre\">1-2 g</span> IV ou IM (<span class=\"kw-chiffre\">50-100 mg/kg</span>, max <span class=\"kw-chiffre\">2 g</span> chez l’enfant)</li><li>Injection <span class=\"kw-alerte\">immédiate</span> ; voie <span class=\"kw-ttt\">IM</span> ou <span class=\"kw-ttt\">intra-osseuse</span> si pas de VVP ; appel <span class=\"kw-alerte\">SAMU</span> (15)</li></ul><p><strong>Contrôle de la source infectieuse</strong></p><ul><li><span class=\"kw-ttt\">Drainage</span> : <span class=\"kw-clinique\">abcès</span> intra-abdominal, épanchement pleural purulent, <span class=\"kw-clinique\">angiocholite</span>, urines en amont d’un obstacle</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-clinique\">péritonite</span>, excision des tissus nécrotiques d’une <span class=\"kw-alerte\">dermohypodermite nécrosante</span></li><li><span class=\"kw-ttt\">Ablation</span> d’un dispositif d’abord vasculaire infecté</li></ul><p><strong>Mesures associées</strong></p><ul><li><span class=\"kw-ttt\">Oxygénothérapie</span> non systématique, cible <span class=\"kw-chiffre\">SpO₂ 96 %</span> si défaut d’apport en O₂</li><li><span class=\"kw-ttt\">Monitorage</span> : scope, PA, SpO₂, <span class=\"kw-def\">surveillance</span> horaire de la diurèse (cathéter artériel + VVC dans l’idéal)</li><li>Sédation et assistance respiratoire au cas par cas</li></ul>","suivi":"<p><strong>Monitorage :</strong> scope, PA non invasive, <span class=\"kw-clinique\">SpO₂</span>, <span class=\"kw-clinique\">surveillance horaire de la diurèse</span>.<br><strong>Cinétique :</strong> <span class=\"kw-bio\">lactatémie</span> répétée, <span class=\"kw-clinique\">régression des marbrures</span>, normalisation de la <span class=\"kw-clinique\">diurèse</span>.<br><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">désescalade</span> dès l’<span class=\"kw-bio\">antibiogramme</span>, durée adaptée au foyer.<br><strong><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">H1</span> :</strong> <span class=\"kw-alerte\">réanimation obligatoire</span> en l’absence d’amélioration.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">mortalité</span> du <span class=\"kw-def\">sepsis</span> <span class=\"kw-chiffre\">&gt; 10 %</span>, du <span class=\"kw-def\">choc septique</span> <span class=\"kw-chiffre\">~40 %</span> ; <span class=\"kw-alerte\">séquelles post-réanimation</span> fréquentes (faiblesse musculaire, troubles neurocognitifs).</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/11.%20Sepsis%20et%20choc%20septique.pdf","label":"Collège CE-MIR — Sepsis & choc septique (PDF)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-157.pdf","label":"Collège Pilly — Sepsis (item 157, PDF)"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/choc-septique","label":"Collège Pédiatrie — Choc septique"},{"href":"https://fr.wikipedia.org/wiki/Score_SOFA","label":"Wikipedia — Score SOFA"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion clinique d’infection — Rechercher une dysfonction d’organe et un état de choc","detail":"<h4>CAT — <span class=\"kw-clinique\">Sepsis</span> & <span class=\"kw-alerte\">choc septique</span> — Suspicion clinique d’infection chez l’enfant et l’adulte</h4>","branches":[{"to":"t-purpura","label":"Purpura nécrotique extensif ≥ 3 mm","color":"red"},{"to":"q-bundle","label":"Infection + dysfonction d’organe (qSOFA ≥ 2)","color":"amber"},{"to":"t-simple","label":"Infection sans dysfonction d’organe","color":"green"}]},{"id":"t-purpura","kind":"terminal","label":"Purpura fulminans — urgence absolue","color":"red","detail":"<h4>Conduite</h4><ul><li>Diagnostic <span class=\"kw-clinique\">clinique</span> au lit du patient en <span class=\"kw-chiffre\">&lt; 30 s</span> ; ne pas attendre d’examen complémentaire ni le transport.</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Céfotaxime</span> <span class=\"kw-chiffre\">1-2 g</span> IV (<span class=\"kw-chiffre\">50 mg/kg</span> chez l’enfant), ou</li><li><span class=\"kw-ttt\">Ceftriaxone</span> <span class=\"kw-chiffre\">1-2 g</span> IV ou IM (<span class=\"kw-chiffre\">50-100 mg/kg</span>, max <span class=\"kw-chiffre\">2 g</span> chez l’enfant)</li><li>Injecter <span class=\"kw-alerte\">immédiatement</span> ; voie <span class=\"kw-ttt\">IM</span> ou <span class=\"kw-ttt\">intra-osseuse</span> si pas de VVP</li></ul><h4>Orientation</h4><ul><li>Appel du <span class=\"kw-alerte\">SAMU</span> (15), transport médicalisé en réanimation ; <span class=\"kw-ttt\">O₂</span> fort débit, pose d’une VVP, <span class=\"kw-ttt\">remplissage par cristalloïdes</span> si <span class=\"kw-alerte\">choc</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Déclaration obligatoire</span> ; identification des sujets-contacts en vue d’une <span class=\"kw-ttt\">antibioprophylaxie</span> (item 151).</li></ul>"},{"id":"q-bundle","kind":"decision","label":"Sepsis — bundle de la 1ʳᵉ heure — Lactates + hémocultures · ATB large spectre IV · cristalloïdes 30 mL/kg · réévaluation à H1","branches":[{"to":"t-amelioration","label":"Amélioration à H1 (PAM ≥ 65, lactates en baisse)","color":"amber"},{"to":"t-choc","label":"Hypotension réfractaire au remplissage","color":"red"}]},{"id":"t-amelioration","kind":"terminal","label":"Sepsis contrôlé — surveillance rapprochée","color":"amber","detail":"<h4>Objectifs atteints</h4><ul><li><span class=\"kw-clinique\">PAM</span> <span class=\"kw-chiffre\">≥ 65 mmHg</span></li><li><span class=\"kw-clinique\">Diurèse</span> <span class=\"kw-chiffre\">≥ 0,5 mL/kg/h</span></li><li><span class=\"kw-clinique\">Régression des marbrures</span></li><li><span class=\"kw-bio\">Correction progressive de la lactatémie</span></li></ul><h4>Conduite</h4><ul><li>Poursuite en milieu de <span class=\"kw-def\">surveillance</span> rapprochée ; <span class=\"kw-ttt\">contrôle de la source infectieuse</span> (<span class=\"kw-ttt\">drainage</span>, chirurgie, ablation de matériel).</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Monitorage</span> (scope, PA, <span class=\"kw-clinique\">SpO₂</span>), <span class=\"kw-def\">surveillance</span> horaire de la <span class=\"kw-clinique\">diurèse</span> ; <span class=\"kw-ttt\">désescalade</span> de l’<span class=\"kw-ttt\">antibiothérapie</span> dès l’<span class=\"kw-bio\">antibiogramme</span>.</li></ul>"},{"id":"t-choc","kind":"terminal","label":"Choc septique — réanimation","color":"red","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Sepsis</span> réfractaire au remplissage + <span class=\"kw-bio\">lactates</span> <span class=\"kw-chiffre\">&gt; 2 mmol/L</span> + besoin de <span class=\"kw-ttt\">vasopresseurs</span> pour <span class=\"kw-chiffre\">PAM ≥ 65 mmHg</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Noradrénaline</span> en 1ʳᵉ intention si <span class=\"kw-chiffre\">PAD &lt; 40</span> ou <span class=\"kw-chiffre\">PAM &lt; 65 mmHg</span></li><li>Monitorage invasif continu de la PA par <span class=\"kw-ttt\">cathéter artériel</span></li><li><span class=\"kw-ttt\">Oxygénothérapie</span> cible <span class=\"kw-chiffre\">SpO₂ 96 %</span> si défaut d’apport associé</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Transfert et prise en charge en réanimation obligatoires</span> ; <span class=\"kw-ttt\">éradication du foyer infectieux</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Pronostic</span> sévère : mortalité <span class=\"kw-chiffre\">~40 %</span>, croissante avec le nombre de défaillances d’organes.</li></ul>"},{"id":"t-simple","kind":"terminal","label":"Infection simple — pas de sepsis","color":"green","detail":"<h4>Clinique</h4><ul><li>Absence de <span class=\"kw-clinique\">dysfonction d’organe</span> : <span class=\"kw-def\">qSOFA &lt; 2</span>, pas de <span class=\"kw-clinique\">marbrures</span> ni d’<span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-bio\">lactates ≤ 2 mmol/L</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> adaptée au foyer ; <span class=\"kw-clinique\">surveillance</span> et <span class=\"kw-def\">réévaluation</span>, car une infection peut évoluer vers le <span class=\"kw-def\">sepsis</span>.</li></ul>"}]},"cards":[]};